#include "dfre/mission_event_region_person.hpp"
#include <iostream>
#include <stdexcept>
#include <vector>
using U=std::uint32_t;using Q=std::uint64_t;
constexpr U ACTION=0x1300100,ACTOR=0x7cca80,PERSON=0x794680;
struct Region{U at;std::vector<unsigned char> bytes;};
int main(){U seed,mutation,fault;while(std::cin>>seed>>mutation>>fault){std::vector<Region> regions;for(auto x:std::vector<std::pair<U,U>>{{ACTION,32},{ACTOR,3*0x114},{PERSON,3*0xb4},{0x8cfa18,4},{0x4fb2cc,64}})regions.push_back({x.first,std::vector<unsigned char>(x.second,static_cast<unsigned char>(seed))});auto byte=[&](U at)->unsigned char&{for(auto& r:regions)if(at>=r.at&&Q(at)-r.at<r.bytes.size())return r.bytes[at-r.at];throw std::runtime_error("Unmapped region person fixture");};auto get=[&](U at,unsigned w){U v=0;for(U i=0;i<w;++i)v|=U(byte(at+i))<<(i*8);return v;};auto put=[&](U at,unsigned w,U v){for(U i=0;i<w;++i)byte(at+i)=static_cast<unsigned char>(v>>(i*8));};
 put(ACTION+4,4,seed%11==0?11:seed%2?13:12);put(ACTION+8,4,(seed/2)%18);put(ACTION+12,4,seed%7==0?0x80000000u:0);put(ACTION+16,4,(seed/36)%16);put(ACTION+20,4,seed%7==0?0x7fffffffu:100);put(ACTION+24,4,seed%5==0?0x80000000u:0);put(ACTION+28,4,seed%5==0?0x7fffffffu:100);put(0x8cfa18,4,seed%13==0?0:seed%17==0?0xffffffffu:3);
 for(U i=0;i<3;++i){put(ACTOR+i*0x114+0xc,4,(seed+i)%9==0?0:PERSON+i*0xb4);put(ACTOR+i*0x114+0x6e,4,((seed%2?1u:2u)<<16)|((seed+i)&0xffff));if(i==1&&seed%3==0)put(ACTOR+i*0x114+0x70,2,0xffff);put(ACTOR+i*0x114+0x72,2,seed%2?2:1);put(ACTOR+i*0x114+0x24,4,i==2&&seed%4==0?101:U(25+i*20));put(ACTOR+i*0x114+0x28,4,U(20+i*20));}
 for(U i=0;i<16;++i)put(0x4fb2cc+i*4,4,0x12345678u^(i*0x112233));Q trace=1469598103934665603ull;U entries=0,operations=0;bool changed=false,wrote=false;auto emit=[&](U tag,U at,U w,U v){++entries;for(U x:{tag,at,w,v})for(U i=0;i<4;++i)trace=(trace^((x>>(i*8))&255))*1099511628211ull;};auto stop=[&](){if(fault&&++operations==fault)throw std::runtime_error("Required region person failure");};auto after_read=[&](U at){if(!changed&&at==ACTOR+0xc){changed=true;if(mutation&1)put(ACTION+4,4,seed%2?12:13);if(mutation&2)put(ACTION+8,4,2);if(mutation&4)put(0x8cfa18,4,1);if(mutation&8)put(ACTION+20,4,0);if(mutation&16)put(ACTOR+0x114+0xc,4,PERSON);}};dfre::MissionEventPersonBindings b;b.read=[&](U at,U w){U value=get(at,w);emit('R',at,w,value);after_read(at);stop();return value;};b.write=[&](U at,U w,U value){put(at,w,value);emit('W',at,w,value);if(!wrote){wrote=true;if(mutation&32)put(ACTION+16,4,0);if(mutation&64)put(ACTOR+0x114+0x70,2,seed%2?2:1);}stop();};b.fp_control=[](){return std::uint16_t(0x037f);};bool failed=false;try{dfre::mission_event_region_person(b,ACTION);}catch(const std::exception&){failed=true;}Q digest=1469598103934665603ull;for(auto& r:regions)for(auto v:r.bytes)digest=(digest^v)*1099511628211ull;std::cout<<failed<<' '<<digest<<' '<<trace<<' '<<entries<<'\n';}}
